2467:{
2468:    //
2469:    // Send a message back to the service that contains the pid of the child process.
2470:    // If the distribution terminates unexpectedly, this pid will be sent to the service so it knows that the instance
2471:    // has terminated.
2472:    //
2473:
2474:    LX_MINI_CREATE_INSTANCE_STEP Step = LxInitCreateInstanceStepMountDisk;
2475:
2476:    auto ReportStatus = [&Channel, &Step](auto result) {
2477:        LX_MINI_INIT_CREATE_INSTANCE_RESULT message{};
2478:        message.Header.MessageType = LxMiniInitMessageCreateInstanceResult;
2479:        message.Header.MessageSize = sizeof(message);
2480:        message.FailureStep = Step;
2481:        message.Result = result;
2482:
2483:        Channel.SendMessage(message);
2484:    };
2485:
2486:    try
2487:    {
2488:        auto* FsType = wsl::shared::string::FromSpan(Buffer, Message->FsTypeOffset);
2489:        auto* MountOptions = wsl::shared::string::FromSpan(Buffer, Message->MountOptionsOffset);
2490:
2491:        //
2492:        // Mount the device.
2493:        //
2494:
2495:        THROW_LAST_ERROR_IF(MountDevice(Message->MountDeviceType, Message->DeviceId, DISTRO_PATH, FsType, Message->Flags, MountOptions) < 0);
2496:
2497:        //
2498:        // Allow /etc/wsl.conf in the user distro to opt-out of GUI support.
2499:        //
2500:        // N.B. A connection for the system distro must established even if the distro opts out
2501:        //      of GUI app support because WslService is waiting to accept a connection.
2502:        //
2503:
2504:        bool enableGuiApps = Config.EnableGuiApps;
2505:        if (Message->Flags & LxMiniInitMessageFlagLaunchSystemDistro && Config.EnableGuiApps)
2506:        {
2507:            Step = LxInitCreateInstanceStepLaunchSystemDistro;
2508:            wil::unique_file File{fopen(DISTRO_PATH ETC_PATH "/wsl.conf", "r")};
2509:            if (File)
2510:            {
2511:                std::vector<ConfigKey> ConfigKeys = {ConfigKey("general.guiApplications", enableGuiApps)};
2512:                ParseConfigFile(ConfigKeys, File.get(), CFG_SKIP_UNKNOWN_VALUES, STRING_TO_WSTRING(CONFIG_FILE));
2513:                File.reset();
2514:            }
2515:
2516:            //
2517:            // If the distro did not opt-out of GUI applications, continue launching the system distro.
2518:            //
2519:
2520:            if (enableGuiApps)
2521:            {
2522:                //
2523:                // Create a tmpfs mount for a shared folder between user and system distro.
2524:                //
2525:
2526:                THROW_LAST_ERROR_IF(UtilMount(nullptr, WSLG_PATH, "tmpfs", 0, nullptr) < 0);
2527:
2528:                THROW_LAST_ERROR_IF(mount(nullptr, WSLG_PATH, nullptr, MS_SHARED, nullptr) < 0);
2529:
2530:                //
2531:                // Create a directory to store x11 sockets.
2532:                //
2533:                // N.B. This needs to be created early so a bind mount into the shared WSLg location
2534:                //      can be created on top of the hard-coded location expected by x11 clients.
2535:                //
2536:
2537:                THROW_LAST_ERROR_IF(UtilMkdir(WSLG_PATH "/" X11_SOCKET_NAME, 0777) < 0);
2538:
2539:                //
2540:                // Create a read-only bind mount of the user distro into the shared WSLg folder so fonts and icons can be accessed.
2541:                //
2542:
2543:                THROW_LAST_ERROR_IF(UtilMount(DISTRO_PATH, WSLG_PATH DISTRO_PATH, nullptr, (MS_BIND | MS_RDONLY), nullptr) < 0);
2544:
2545:                THROW_LAST_ERROR_IF(UtilMount(nullptr, WSLG_PATH DISTRO_PATH, nullptr, (MS_RDONLY | MS_REMOUNT | MS_BIND), nullptr) < 0);
2546:
2547:                //
2548:                // Create a child process in a new mount, pid, and UTS namespace (with a shared IPC namespace).
2549:                // This child process will become the user distro init daemon.
2550:                //
2551:
2552:                auto ChildPid = CLONE(CLONE_NEWNS | CLONE_NEWPID | CLONE_NEWUTS | SIGCHLD);
2553:                THROW_LAST_ERROR_IF(ChildPid < 0);
2554:
2555:                if (ChildPid > 0)
2556:                {
2557:                    //
2558:                    // Close the socket for the user distro and launch the system
2559:                    // distro. This method does not return.
2560:                    //
2561:
2562:                    Channel.Close();
2563:
2564:                    LaunchSystemDistro(
2565:                        SystemDistroSocketFd.get(),
2566:                        SYSTEM_DISTRO_PATH,
2567:                        Config,
2568:                        wsl::shared::string::FromSpan(Buffer, Message->VmIdOffset),
2569:                        wsl::shared::string::FromSpan(Buffer, Message->DistributionNameOffset),
2570:                        wsl::shared::string::FromSpan(Buffer, Message->SharedMemoryRootOffset),
2571:                        wsl::shared::string::FromSpan(Buffer, Message->InstallPathOffset),
2572:                        wsl::shared::string::FromSpan(Buffer, Message->UserProfileOffset),
2573:                        ChildPid);
2574:                }
2575:            }
2576:
2577:            SystemDistroSocketFd.reset();
2578:        }
2579:
2580:        //
2581:        // Launch the distro init daemon, this method does not return.
2582:        //
2583:
2584:        Step = LxInitCreateInstanceStepLaunchInit;
2585:        LaunchInit(
2586:            Channel.Socket(),
2587:            DISTRO_PATH,
2588:            enableGuiApps,
2589:            Config,
2590:            wsl::shared::string::FromSpan(Buffer, Message->VmIdOffset),
2591:            wsl::shared::string::FromSpan(Buffer, Message->DistributionNameOffset),
2592:            nullptr,
2593:            wsl::shared::string::FromSpan(Buffer, Message->InstallPathOffset),
2594:            wsl::shared::string::FromSpan(Buffer, Message->UserProfileOffset));
2595:    }
2596:    catch (...)
2597:    {
2598:        ReportStatus(wil::ResultFromCaughtException());
2599:        _exit(1);
2600:    }
2601:}
