1245:            Result = -1;
1246:            goto InitCreateSessionLeaderExit;
1247:        }
1248:
1249:        // Note: The call to accept() must be done in the child because if accept() takes a long time, it can block the creation
1250:        // of other session leaders. See https://github.com/microsoft/WSL/issues/9114.
1251:
1252:        SessionLeader = UtilCreateChildProcess(
1253:            "SessionLeader", [ListenSocket = std::move(ListenSocket), &Channel, &Config, Mask = Config.Umask, SocketAddress]() {
1254:                umask(Mask);
1255:                Channel.Close();
1256:
1257:                THROW_LAST_ERROR_IF(UtilRestoreBlockedSignals() < 0);
1258:
1259:                wsl::shared::SocketChannel channel{
1260:                    {UtilAcceptVsock(ListenSocket.get(), SocketAddress, SESSION_LEADER_ACCEPT_TIMEOUT_MS)}, "SessionLeader"};
1261:                if (channel.Socket() < 0)
1262:                {
1263:                    LOG_ERROR("UtilAcceptVsock() failed for session leader {}", errno);
1264:                    _exit(1);
1265:                }
1266:
1267:                SessionLeaderEntryUtilityVm(channel, Config);
1268:            });
1269:    }
1270:
1271:    if (SessionLeader < 0)
1272:    {
1273:        Result = -1;
1274:        goto InitCreateSessionLeaderExit;
1275:    }
1276:
1277:    Result = 0;
