843:void WslCoreVm::AddDrvFsShare(_In_ bool Admin, _In_ HANDLE UserToken)
844:{
845:    THROW_HR_IF(HCS_E_TERMINATED, !m_system);
846:
847:    // Allow the Plan 9 server to create NT symlinks.
848:    //
849:    // N.B. This may fail for unelevated users, however symlink creation will
850:    //      succeed even without this privilege if developer mode is enabled.
851:    wsl::windows::common::security::EnableTokenPrivilege(UserToken, SE_CREATE_SYMBOLIC_LINK_NAME);
852:
853:    // Set the 9p port and virtio tag.
854:    const UINT32 port = Admin ? LX_INIT_UTILITY_VM_PLAN9_DRVFS_ADMIN_PORT : LX_INIT_UTILITY_VM_PLAN9_DRVFS_PORT;
855:    const PCWSTR tag = Admin ? TEXT(LX_INIT_DRVFS_ADMIN_VIRTIO_TAG) : TEXT(LX_INIT_DRVFS_VIRTIO_TAG);
856:    AddPlan9Share(
857:        TEXT(LX_INIT_UTILITY_VM_DRVFS_SHARE_NAME), L"\\\\?", port, (hcs::Plan9ShareFlags::AllowOptions | hcs::Plan9ShareFlags::AllowSubPaths), UserToken, tag);
858:
859:    const auto virtiofsInitialized = Admin ? m_adminDrvfsToken.is_valid() : m_drvfsToken.is_valid();
860:    if (m_vmConfig.EnableVirtioFs && !virtiofsInitialized)
861:    {
862:        // Add virtiofs devices associating indices with paths from the fixed drive bitmap. These devices support
