272:void WslCoreInstance::ReadOOBEResult(wil::unique_socket&& Socket, wsl::windows::service::DistributionRegistration&& registration)
273:{
274:    wsl::shared::SocketChannel channel(std::move(Socket), "OOBE", m_destroyingEvent.get());
275:
276:    const auto* oobeResult = channel.ReceiveMessageOrClosed<LX_INIT_OOBE_RESULT>().first;
277:
278:    if (oobeResult == nullptr)
279:    {
280:        LOG_HR_MSG(E_FAIL, "OOBE channel closed");
281:        return;
282:    }
283:
284:    // Logs the result of the OOBE process
285:    WSL_LOG_TELEMETRY(
286:        "OOBEResult",
287:        PDT_ProductAndServicePerformance,
288:        TraceLoggingValue(oobeResult->Result, "Result"),
289:        TraceLoggingValue(oobeResult->DefaultUid, "DefaultUid"),
290:        TraceLoggingValue(m_configuration.Name.c_str(), "Name"),
291:        TraceLoggingValue(2, "Version"));
292:
293:    if (oobeResult->Result == 0)
294:    {
295:        // OOBE was successful, don't run it again.
296:        m_configuration.RunOOBE = false;
297:        registration.Write(wsl::windows::service::Property::RunOOBE, 0);
298:
299:        if (oobeResult->DefaultUid != -1)
300:        {
301:            registration.Write(wsl::windows::service::Property::DefaultUid, static_cast<int>(oobeResult->DefaultUid));
302:            m_defaultUid = static_cast<int>(oobeResult->DefaultUid);
303:        }
304:    }
305:}
